import { Ltr, PageHeader, Panel, PanelHeader, Status, Table, Td, Th, Tr } from "@his/ui";
import { InvoiceFilters } from "./invoice-filters";

/*
 * The Billing product. It knows nothing about the app around it: the route
 * shell generated by scripts/compose.mjs mounts it and passes the language.
 * If a customer has not bought Billing, nothing imports this file, so none
 * of it is compiled into that customer's build.
 */

/** searched for by scripts/verify-build.mjs — proves server code reached the build */
export const BILLING_SERVER_MARK = "his-billing-server-module";

type Lang = "en" | "ar";
type L = Record<Lang, string>;

const T = {
  title: { en: "Invoices", ar: "الفواتير" },
  subtitle: { en: "4 open this week · 4,730 SAR", ar: "4 مفتوحة هذا الأسبوع · 4,730 ر.س" },
  panel: { en: "This week", ar: "هذا الأسبوع" },
  cols: {
    no: { en: "Invoice", ar: "الفاتورة" },
    patient: { en: "Patient", ar: "المريض" },
    payer: { en: "Payer", ar: "الجهة الدافعة" },
    amount: { en: "Amount", ar: "المبلغ" },
    status: { en: "Status", ar: "الحالة" },
  },
} satisfies Record<string, L | Record<string, L>>;

const INVOICES: { no: string; patient: L; payer: L; amount: string; state: "done" | "pending" | "attention"; status: L }[] = [
  { no: "INV-24081", patient: { en: "Layla Mansour", ar: "ليلى منصور" }, payer: { en: "Bupa Gold", ar: "بوبا ذهبي" }, amount: "1,240.00", state: "done", status: { en: "Paid", ar: "مدفوعة" } },
  { no: "INV-24082", patient: { en: "Khalid Al-Harbi", ar: "خالد الحربي" }, payer: { en: "Self pay", ar: "دفع ذاتي" }, amount: "380.00", state: "attention", status: { en: "Unpaid", ar: "غير مدفوعة" } },
  { no: "INV-24083", patient: { en: "Noura Al-Qahtani", ar: "نورة القحطاني" }, payer: { en: "Tawuniya", ar: "التعاونية" }, amount: "2,150.00", state: "pending", status: { en: "Claim pending", ar: "مطالبة معلّقة" } },
  { no: "INV-24084", patient: { en: "Abdullah Nasser", ar: "عبدالله ناصر" }, payer: { en: "Self pay", ar: "دفع ذاتي" }, amount: "960.00", state: "attention", status: { en: "Outstanding", ar: "مستحقة" } },
];

export function InvoicesPage({ lang }: { lang: Lang }) {
  const cur = lang === "ar" ? "ر.س" : "SAR";
  return (
    <div data-module={BILLING_SERVER_MARK}>
      <PageHeader title={T.title[lang]} subtitle={T.subtitle[lang]} />
      <Panel>
        <PanelHeader title={T.panel[lang]} />
        <InvoiceFilters lang={lang} />
        <Table label={T.title[lang]}>
          <thead>
            <tr>
              <Th>{T.cols.no[lang]}</Th>
              <Th>{T.cols.patient[lang]}</Th>
              <Th>{T.cols.payer[lang]}</Th>
              <Th>{T.cols.amount[lang]}</Th>
              <Th>{T.cols.status[lang]}</Th>
            </tr>
          </thead>
          <tbody>
            {INVOICES.map((inv) => (
              <Tr key={inv.no}>
                <Td tone="id">
                  <Ltr>{inv.no}</Ltr>
                </Td>
                <Td>{inv.patient[lang]}</Td>
                <Td tone="dim">{inv.payer[lang]}</Td>
                <Td>
                  <Ltr>{inv.amount}</Ltr> {cur}
                </Td>
                <Td>
                  {/* money is operational state: <Status>, never a clinical colour */}
                  <Status state={inv.state}>{inv.status[lang]}</Status>
                </Td>
              </Tr>
            ))}
          </tbody>
        </Table>
      </Panel>
    </div>
  );
}
